import{_ as o,o as r,c as l,ah as i}from"./chunks/framework.DjU4PSOm.js";const _=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[{"level":2,"title":"이 문서에 대하여","slug":"이-문서에-대하여","link":"#이-문서에-대하여","children":[]},{"level":2,"title":"1주차 — 윤리학이란 무엇인가","slug":"_1주차-—-윤리학이란-무엇인가","link":"#_1주차-—-윤리학이란-무엇인가","children":[]},{"level":2,"title":"2주차 — 아리스토텔레스와 에우다이모니아","slug":"_2주차-—-아리스토텔레스와-에우다이모니아","link":"#_2주차-—-아리스토텔레스와-에우다이모니아","children":[]},{"level":2,"title":"3주차 — 습관화, 헥시스, 중용, 실천적 지혜","slug":"_3주차-—-습관화-헥시스-중용-실천적-지혜","link":"#_3주차-—-습관화-헥시스-중용-실천적-지혜","children":[]},{"level":2,"title":"4주차 — 칸트","slug":"_4주차-—-칸트","link":"#_4주차-—-칸트","children":[]},{"level":2,"title":"5주차 — 칸트 II: 정언명령 (슬라이드 26-2 윤리학 5강, 한글본 29쪽)","slug":"_5주차-—-칸트-ii-정언명령-슬라이드-26-2-윤리학-5강-한글본-29쪽","link":"#_5주차-—-칸트-ii-정언명령-슬라이드-26-2-윤리학-5강-한글본-29쪽","children":[{"level":3,"title":"5주차 슬라이드 중 아직 강의로 다뤄지지 않은 부분","slug":"_5주차-슬라이드-중-아직-강의로-다뤄지지-않은-부분","link":"#_5주차-슬라이드-중-아직-강의로-다뤄지지-않은-부분","children":[]}]},{"level":2,"title":"6주차 — 벤담 (슬라이드 26-2 윤리학 6강, 18쪽)","slug":"_6주차-—-벤담-슬라이드-26-2-윤리학-6강-18쪽","link":"#_6주차-—-벤담-슬라이드-26-2-윤리학-6강-18쪽","children":[]}],"relativePath":"philosophy/Ethics/08. 슬라이드에 없는 강의 추가 내용.md","filePath":"philosophy/Ethics/08. 슬라이드에 없는 강의 추가 내용.md"}'),n={name:"philosophy/Ethics/08. 슬라이드에 없는 강의 추가 내용.md"};function s(g,t,e,u,a,q){return r(),l("div",null,[...t[0]||(t[0]=[i('<h2 id="이-문서에-대하여" tabindex="-1">이 문서에 대하여 <a class="header-anchor" href="#이-문서에-대하여" aria-label="Permalink to &quot;이 문서에 대하여&quot;">​</a></h2><p>교수님이 Canvas에 올린 공식 슬라이드(PDF)와 실제 TransLive 강의 자막을 대조해서, <strong>슬라이드에는 없고 강의에서만 구두로 설명된 내용</strong>(구체적 예시, 문장 단위 정독, 학생과의 즉석 Q&amp;A, 슬라이드보다 상세한 논증 전개)만 골라 정리했습니다. 슬라이드에 이미 있는 핵심 개념·정의·구조는 반복하지 않았습니다. 완전한 문장 단위 대조는 아니며, <strong>슬라이드에 없는 실질적 내용 위주</strong>로 추렸습니다.</p><hr><h2 id="_1주차-—-윤리학이란-무엇인가" tabindex="-1">1주차 — 윤리학이란 무엇인가 <a class="header-anchor" href="#_1주차-—-윤리학이란-무엇인가" aria-label="Permalink to &quot;1주차 — 윤리학이란 무엇인가&quot;">​</a></h2><p>슬라이드는 오리엔테이션(언어 정책, 평가, 커리큘럼)과 Rachels 1장 요약(최소 개념, 딜레마 등)을 다루지만, 아래는 슬라이드에 없는 것들:</p><ul><li><strong>나이에 따른 위계 사례</strong>: 윤리(ethics) vs 도덕(morality) 구별을 설명하며 든, 나이가 다른 사람들을 다르게 대우하는 구체적 사례 — 슬라이드의 &quot;언어학 비유&quot;만 있고 이 사례는 없음.</li><li><strong>&quot;어떻게 살아야 하는가, </strong>그리고 왜<strong>&quot;</strong> — 소크라테스 정식을 인용할 때 &quot;그리고 왜(and why)&quot;라는 구절 자체가 왜 중요한지에 대한 정독 포인트. 슬라이드는 인용문만 보여주고 이 구문 분석은 생략.</li><li><strong>부정행위 친구 사례의 세 이론 비교</strong>: 친구의 시험 부정행위를 목격했을 때 — 덕윤리는 &quot;정직하고 용기 있는 사람이라면 어떻게 할까&quot;, 의무론은 &quot;이 행동을 용인하는 원칙이 보편화될 수 있는가&quot;, 공리주의는 &quot;어느 쪽이 더 큰 해를 줄이는가&quot;를 각각 묻는다는 비교. 슬라이드는 &quot;everyone cheats&quot; 오류만 언급하고 이 3이론 비교는 없음.</li><li><strong>&quot;만족한 짐승&quot; 비유</strong>: 성찰 없는 삶을 상징하는 표현 — 슬라이드의 소크라테스 인용문에는 없음.</li><li><strong>Rachels 텍스트의 &quot;handicapped children&quot; 표현에 대한 언어 민감성 논의</strong>: &quot;장애가 있는 아이들(children with disabilities)&quot;이라는 표현으로 바꿔 부르는 현대적 감수성 논의, AI 시대의 지역별 학력 격차 예시. 슬라이드 15는 원문 스캔 이미지만 보여주고 이 논의는 없음.</li></ul><h2 id="_2주차-—-아리스토텔레스와-에우다이모니아" tabindex="-1">2주차 — 아리스토텔레스와 에우다이모니아 <a class="header-anchor" href="#_2주차-—-아리스토텔레스와-에우다이모니아" aria-label="Permalink to &quot;2주차 — 아리스토텔레스와 에우다이모니아&quot;">​</a></h2><p>슬라이드는 텔레올로지·에우다이모니아·1권 7장 정독의 핵심 뼈대를 담고 있지만, 다음은 강의에서만 나온 세부사항:</p><ul><li><strong>스마트폰/소셜미디어 구체 사례</strong>: &quot;요즘 스마트폰 과사용 경험 있지 않나요?&quot;, 좋아요·댓글 반응에 따른 자기만족·불안 경험 등 학생들에게 직접 던진 질문들. 슬라이드는 &quot;소셜미디어가 가시성을 가치와 동일시하게 만든다&quot;는 한 문장 요약뿐.</li><li><strong>&quot;철학과 지원 증가&quot; 화두</strong>: AI 시대 생존 전략으로 철학을 선택하는지, 다른 동기인지 묻는 질의. 슬라이드에 없음.</li><li><strong>삶을 계속 미루는 문제의 구체적 예시</strong>: &quot;졸업 후에 인생이 시작된다&quot;, &quot;승진 후에&quot;, &quot;충분한 사회적 인정을 받은 후에&quot; 등 구체적 예문들. 슬라이드는 &quot;Life will begin after graduation. After promotion. After recognition.&quot;로 짧게만 언급.</li><li><strong>1권 7장 문장 단위 정독의 그리스어 문법 분석</strong>: 아가톤(agathon)·텔로스(telos)·텔레이온(teleion) 각 용어가 원문 문장에서 정확히 어느 구절에 대응하는지, &quot;그것을 위하여 모든 것이 행해지는 바로 그것&quot;이라는 구문이 왜 목적을 정의하는지에 대한 문장별 해설. 슬라이드는 최종 결론(개념 정의 카드)만 제공.</li><li><strong>일원론(monism)/이원론(dualism)/다원론(pluralism) 삼분</strong> 설명 — 슬라이드는 &quot;ethical monism has not yet been proved&quot;라고만 언급하고, monism/dualism/pluralism을 나란히 정의하는 강의 설명은 없음.</li><li><strong>친구관계·중병 가족 돌봄 충돌 사례</strong>: 경력과 중병 가족 돌봄이 충돌할 때 &quot;둘 다 가치 있다&quot;는 말만으로는 결정이 안 된다는 구체적 딜레마. 슬라이드 discussion question(19페이지 &quot;Plurality of Goods&quot;)은 있지만 이 구체적 사례는 없음.</li><li><strong>일제강점기 독립운동가 사례</strong>: &quot;행복을 정의를 위해 희생할 수 있는가&quot;라는 논의 질문에 실제 예시로 언급됨. 슬라이드는 추상적 질문만 있고 이 역사적 사례는 없음.</li><li><strong>경쟁 세일즈 인간관계/명예 불안정성에 대한 구체 설명 확장</strong> — 슬라이드보다 더 풍부한 예시로 진행됨(광고와 충동구매, 경쟁적 제도의 승리 vs 정의 등).</li></ul><h2 id="_3주차-—-습관화-헥시스-중용-실천적-지혜" tabindex="-1">3주차 — 습관화, 헥시스, 중용, 실천적 지혜 <a class="header-anchor" href="#_3주차-—-습관화-헥시스-중용-실천적-지혜" aria-label="Permalink to &quot;3주차 — 습관화, 헥시스, 중용, 실천적 지혜&quot;">​</a></h2><p>가장 많은 추가 내용이 있었던 주차. 슬라이드에 없는 것들:</p><ul><li><strong>언어 습득 비유의 구체적 질의</strong>: &quot;한국어를 몇 살에 배우기 시작했나요?&quot;라는 실제 질문과, 언어 습득 과정(교사·가족·친구와의 일상적 연습)을 윤리적 능력 발달과 나란히 놓는 상세 설명. 슬라이드에는 이 비유 자체가 없음(슬라이드는 돌 비유만 사용).</li><li><strong>싱가포르 쓰레기 무단투기 처벌 사례</strong>: 법의 교육적 기능을 설명하며 든 구체적 국가 사례. 슬라이드는 이 사례가 없고 일반적 서술(&quot;tax law, education law...&quot;)만 있음.</li><li><strong>대학 부정행위 환경 사례</strong>: 대학이 공식적으로 부정행위를 금지하면서 동시에 경쟁적 환경을 조성해 부정행위를 조장하는 모순 사례. 슬라이드에 없음.</li><li><strong>한국 정치 체제가 무엇을 함양하는지 묻는 질의</strong>: &quot;경쟁? 불안감? 패배에 대한 두려움?&quot;라는 학생 대상 실제 질문. 슬라이드는 일반론만 서술.</li><li><strong>연구자의 정직/부정직 습관화 사례, 학대적 리더십 사례</strong>: 반복된 행동이 행위자 자신을 변화시킨다는 논점의 구체적 현대 예시(연구 부정행위, 리더십 학대). 슬라이드는 건축가/음악가 비유만 사용.</li><li><strong>&quot;당신의 습관은 무엇인가?&quot; 직접 질문</strong>: 일상 루틴과 도덕적 습관의 차이를 설명하며 학생들에게 던진 질문. 슬라이드에 없음.</li><li><strong>넛징(nudging) 자판기 예시</strong>: 과자 자판기 배치가 식습관을 형성하는 구체적 사례. 슬라이드는 &quot;default setting&quot; 정도만 언급.</li><li><strong>소크라테스적 주지주의 비판의 구체적 사례들</strong>: 과음이 해로운 걸 알면서도 못 끊는 경우, 거짓말이 잘못인 걸 알면서도 명예 위협시 거짓말하는 경우 — akrasia(의지의 나약함) 설명에 쓰인 구체적 예시. 슬라이드는 &quot;akrasia&quot;라는 용어만 소개.</li><li><strong>자선단체 기부 동기의 다중성</strong>: 관심/전략/마케팅 이점이 동시에 작용하는 기업 기부 사례 — 이건 사실 4주차 슬라이드에 있음(주의: 이 항목은 4주차 자막에서 언급되었으나 위치상 3주차 논의와 혼동 주의).</li><li><strong>온라인 분노 사례</strong>: 잘못된 대상에게 향하거나 사실 확인 전에 일어나거나 가시성을 추구하는 온라인 분노의 병리 — 슬라이드는 &quot;Appropriate anger&quot; 항목에 간단히만 언급, 온라인 특유의 병리적 패턴 설명은 강의에서만.</li><li><strong>AI 학생 이탈 예측 시스템의 구체적 질문 목록</strong>: &quot;학생에게 연락해야 하는가? 개인정보는? 낙인효과는? 데이터가 불평등을 재생산하는가? 누가 책임지는가?&quot; — 슬라이드도 유사 질문을 담고 있으나(19페이지), 강의는 더 풍부한 질문 목록을 제시.</li><li><strong>기후변화 지식과 행동의 괴리, 사회제도의 편견(암묵적 편견) 논의</strong>: 명시적으로 평등을 지지하면서 무의식적으로 특정 집단과 능력을 연관짓는 사례 등 — 슬라이드보다 상세.</li></ul><h2 id="_4주차-—-칸트" tabindex="-1">4주차 — 칸트 <a class="header-anchor" href="#_4주차-—-칸트" aria-label="Permalink to &quot;4주차 — 칸트&quot;">​</a></h2><p>슬라이드가 매우 상세해서(35페이지) 겹치는 부분이 많지만, 강의에서만 나온 것:</p><ul><li><strong>자살/우울증 관련 신중한 주의사항</strong>: &quot;생명 보존&quot; 예시를 설명하며 &quot;이것은 자살, 정신질환, 견딜 수 없는 고통에 대한 완전한 논의가 아니며, 심각한 우울증을 겪는 사람을 의료·사회적 맥락 없이 판단하는 데 사용되어서는 안 된다&quot;는 교수님의 명시적 주의. 슬라이드는 이 예시를 간단히만 언급(18페이지)하고 이 윤리적 주의사항은 없음.</li><li><strong>쇼펜하우어 인용</strong>: 인간이 자신의 가장 깊은 동기를 완전히 확신할 수 없다는 논점에 쇼펜하우어를 명시적으로 인용. 슬라이드에 이 인용은 없음.</li><li><strong>아담 스미스의 &quot;공정한 관찰자&quot;와의 비교</strong>: 칸트의 &quot;합리적이고 공정한 관찰자&quot; 사고실험이 애덤 스미스의 이론과 정확히 같지는 않다는 명시적 구별. 슬라이드에 없음.</li><li><strong>부패한 관리·부정직 기업의 구체적 사고실험</strong>: &quot;부패한 관리가 부유하고 권력 있고 건강하고 존경받는다면&quot;, &quot;소비자를 속이고 노동자를 착취해 이익을 낸 기업&quot; — 슬라이드는 추상적 개념만 제시하고 이 구체적 사례는 강의에서 추가.</li><li><strong>자동차 운전 사례(moral luck)</strong>: 이 비유 자체는 슬라이드 28페이지에 있으나(두 careful/careless drivers), 강의 자막에는 해당 부분이 아직 도달하지 않음 — 참고로 이 세션의 자막은 &quot;worthiness to be happy&quot; 결론부에서 끝났으므로 슬라이드 후반부(자율성, AI 응용, 기후/공급망, 실천 프레임워크)는 <strong>5주차 강의 앞부분에서 다뤄졌다</strong> (아래 5주차 절 참고).</li></ul><h2 id="_5주차-—-칸트-ii-정언명령-슬라이드-26-2-윤리학-5강-한글본-29쪽" tabindex="-1">5주차 — 칸트 II: 정언명령 (슬라이드 <code>26-2 윤리학 5강</code>, 한글본 29쪽) <a class="header-anchor" href="#_5주차-—-칸트-ii-정언명령-슬라이드-26-2-윤리학-5강-한글본-29쪽" aria-label="Permalink to &quot;5주차 — 칸트 II: 정언명령 (슬라이드 `26-2 윤리학 5강`, 한글본 29쪽)&quot;">​</a></h2><p>4주차 슬라이드 29~35(자율성, AI·채용·기후 응용, 5단계 프레임워크)는 5주차 강의 앞부분에서 <strong>빠르게 다뤄졌다</strong>. 슬라이드 5강과 자막을 대조했을 때 슬라이드에 없고 강의에서만 나온 것:</p><ul><li><strong>출석·휴일 공지</strong>: 목·금 휴일이라 수업 없음, 녹화 강의가 보충 수업, 수업 중 나갔다 들어오는 건 허용하지만 <strong>돌아오지 않으면 감점</strong>. (슬라이드 없음)</li><li><strong>학습 목표가 10개</strong>: 슬라이드 14쪽은 4개(준칙 정의 / 명령 구별 / 공식 적용 / 비판적 평가)만 적었지만, 강의는 10개로 풀었다 — 의무에서 정언명령으로 가는 이유, <strong>자기·타인에 대한 의무와 완전·불완전 의무로 나누는 이유</strong>, 자연법칙 정식과 보편법칙 정식의 차이, 보편성의 역할, 칸트의 철학사적 의의 등.</li><li><strong>아리스토텔레스 vs 칸트 비교의 상세 예시</strong>: 용감한 사람은 두려움을, 절제하는 사람은 쾌락을, 정의로운 사람은 타인의 요구를 적절히 지각하도록 <strong>습관화</strong>된 사람이라는 설명, 그리고 <strong>&quot;희화화하지 말라&quot;</strong> — 아리스토텔레스가 이성을, 칸트가 도덕 교육·성격을 무시하는 게 아니라 차이는 <strong>토대</strong>에 있다는 단서. (슬라이드 13쪽은 두 질문만 대비)</li><li><strong>계몽주의·뉴턴 과학 배경</strong>: 근대 수학·뉴턴 자연과학이 칸트의 상상력을 형성했지만 <strong>윤리를 수학·수치 계산·방정식으로 환원하려던 것이 아니다</strong>라는 설명, 그리고 &quot;많은 사람이 거짓말한다 → 거짓말이 허용된다&quot;는 추론이 성립하지 않는다는 예. 슬라이드 15쪽은 모토·a priori·도덕적 평등만 요약.</li><li><strong>a priori의 오해 방지</strong>: 자의적이거나 삶과 단절된 것이 아니라 <strong>권위가 관찰에서 오지 않는다</strong>는 뜻이라는 설명. 도덕법은 인기·수익성·감정적 매력·편의가 아니라 합리적 형식 때문에 구속한다.</li><li><strong>&quot;계몽 이전엔 친족·부유층이 도덕 의무에서 면제됐다&quot;</strong>: 보편성에 집중하는 이유를 역사적으로 설명한 마지막 대목. 귀족·교수·학생·정치인·사업주·시민이 모두 같은 요구 아래 선다는 열거.</li><li><strong>정독 문장별 해설</strong> (슬라이드 18~20쪽은 공식과 요약 해설만): <ul><li>&quot;그러므로(therefore)&quot;가 정식이 <strong>고립된 구호가 아니라 앞선 논증의 귀결</strong>임을 보여 준다는 분석, &quot;오직 하나의&quot; 정언명령이 <strong>도덕의 통일된 토대</strong>를 뜻한다는 설명.</li><li>학생이 마주치는 여러 규칙(표절·위조·기만 금지, 비밀 존중), <strong>연구 윤리의 여러 규칙(출처 인용·동의·조작 금지·이해충돌 공개)을 하나의 더 깊은 원칙의 적용으로 보는</strong> 사례.</li><li>&quot;의무가 공허한 개념이 아닌지 미결로 두더라도&quot; 대목: 토대는 『정초』 후반의 <strong>자유·자율</strong>에서 나온다는 예고, <strong>AI 윤리의 &quot;책임&quot;</strong> 비유(책임질 수 있는지 결정하기 전에도 책임의 개념은 분석 가능).</li><li>&quot;교수가 출처를 인용할 의무가 있다고 하면 무엇이 그것을 의무로 만드는가&quot; 질문.</li><li><strong>자연 = 법칙이 지배하는 사건의 질서</strong>(숲·동물·강·산이 아니라 형식적 정의), <strong>중력은 누가 싫어해도 멈추지 않는다</strong> 비유, 도덕 행위자가 기계적 객체라는 뜻이 아니라는 단서.</li></ul></li><li><strong>4주차 응용 슬라이드를 구술로 확장한 부분</strong>: 부(wealth)가 <strong>운명의 선물</strong>이며 상속·특권·구조의 산물일 수 있다는 점, 정치권력이 권리를 지킬 수도 파괴할 수도 있다는 점, 취약 집단을 배제하며 번영하는 사회 / 부정의로부터 이익을 얻으며 행복한 사람과 &quot;행복 vs 자격&quot;의 연결, 알고리즘 채용에서 <strong>탈락 기준을 알 수도 물을 수도 없는</strong> 사람의 문제, 미래 세대는 <strong>동의할 수 없지만</strong> 도덕적으로 고려할 만한 인격이라는 점과 <strong>비인간 존재</strong>까지 포함할 수 있는가라는 질문.</li><li><strong>도덕적 운 토론 질문</strong>: &quot;법과 도덕이 운을 같은 방식으로 평가해야 하나? 왜 엄격한 처벌은 칸트적 도덕 가치보다 결과에 더 의존하는가?&quot; (슬라이드 6쪽에는 이 질문 없음)</li></ul><h3 id="_5주차-슬라이드-중-아직-강의로-다뤄지지-않은-부분" tabindex="-1">5주차 슬라이드 중 아직 강의로 다뤄지지 않은 부분 <a class="header-anchor" href="#_5주차-슬라이드-중-아직-강의로-다뤄지지-않은-부분" aria-label="Permalink to &quot;5주차 슬라이드 중 아직 강의로 다뤄지지 않은 부분&quot;">​</a></h3><p>강의는 슬라이드 <strong>19~20쪽(보편법칙·자연법칙 정식) 도입부</strong>에서 시간이 끝났다. 남은 슬라이드:</p><ul><li>20쪽 후반: 자연법칙 정식의 <strong>거짓 약속</strong> 예시 (개념상의 모순)</li><li>21쪽: <strong>칸트의 네 가지 의무 예시</strong> (자신에 대한 완전/불완전, 타인에 대한 완전/불완전)</li><li>22쪽: <strong>보편화 검증 절차</strong> (준칙 확인 → 의무 유형 → 보편화 → 개념상/의지상 모순)</li><li>23쪽: 현대적 적용 (주의 포획 인터페이스, 연구 증거 은폐, 정치적 허위정보)</li><li>24쪽: 철학적·역사적 의의</li><li>25~26쪽: <strong>강점과 한계</strong> (형식주의/도덕적 게리맨더링, 맥락·예외, 감정·배려, 결과, 사회구조·권력, 비인간 생명)</li><li>27쪽: 칸트와 아리스토텔레스의 상호 교정</li><li>28~29쪽: 토론 질문과 최종 요약 (다음 주제: <strong>인간성의 정식</strong> — 인간성을 항상 목적으로, 결코 단순한 수단으로만 대하지 않기)</li></ul><hr><h2 id="_6주차-—-벤담-슬라이드-26-2-윤리학-6강-18쪽" tabindex="-1">6주차 — 벤담 (슬라이드 <code>26-2 윤리학 6강</code>, 18쪽) <a class="header-anchor" href="#_6주차-—-벤담-슬라이드-26-2-윤리학-6강-18쪽" aria-label="Permalink to &quot;6주차 — 벤담 (슬라이드 `26-2 윤리학 6강`, 18쪽)&quot;">​</a></h2><p>이 주차는 <strong>자막이 아직 없어</strong> 비교하지 않았다. 강의 자막을 받으면 같은 방식으로 정리한다.</p>',24)])])}const d=o(n,[["render",s]]);export{_ as __pageData,d as default};
